12	function NavDropdown({ item }: { item: NavItem }) {
13	  return (
14	    <div className="group relative">
15	      <button className="flex items-center gap-1 text-sm font-medium text-foreground/80 transition-colors hover:text-foreground">
16	        {item.label}
17	        <ChevronDown className="h-3.5 w-3.5 transition-transform group-hover:rotate-180" />
18	      </button>
19	      <div className="invisible absolute left-0 top-full z-50 mt-2 min-w-[200px] rounded-lg border bg-popover p-2 opacity-0 shadow-lg transition-all group-hover:visible group-hover:opacity-100">
20	        {item.children?.map((child) => (
21	          <Link
22	            key={child.href}
23	            href={child.href}
24	            className="flex items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors hover:bg-accent"
25	          >
26	            {child.label}
27	            {child.comingSoon && (
28	              <span className="rounded-full bg-brand-yellow/20 px-2 py-0.5 text-[10px] font-medium text-brand-navy">
29	                Soon
30	              </span>
31	            )}
32	          </Link>
33	        ))}
34	      </div>
35	    </div>
36	  );
37	}
