export interface NavItem {
  label: string;
  href: string;
  description?: string;
  children?: NavItem[];
  external?: boolean;
  comingSoon?: boolean;
}

import type { NavItem } from "@/types/navigation";

export const NAV_ITEMS: NavItem[] = [
  {
    label: "Solutions",
    href: "#",
    children: [
      {
        label: "Web Development",
        href: "/services/website-development",
        description: "Fast, scalable websites built for performance and growth.",
      },
      {
        label: "UI/UX Design",
        href: "/services/ui-ux-design",
        description:
          "User-centric designs that drive engagement and conversions.",
        comingSoon: true,
      },
      {
        label: "Graphic Design",
        href: "/services/graphics-design",
        description: "Visually striking designs that strengthen your brand.",
        comingSoon: true,
      },
      {
        label: "App Development",
        href: "/services/app-development",
        description: "Custom apps designed for speed and scalability.",
        comingSoon: true,
      },
    ],
  },
  { label: "How It Works", href: "/how-it-works" },
  { label: "Pricing", href: "/pricing" },
  { label: "Our Work", href: "/our-works" },
  { label: "Our Mission", href: "/our-mission" },
  {
    label: "Resources",
    href: "#",
    children: [
      { label: "Blog", href: "/blog" },
      { label: "Help Center", href: "https://help.boldteq.com", external: true },
    ],
  },
];

export const CTA_NAV: NavItem[] = [
  { label: "Login", href: "https://portal.boldteq.com/", external: true },
  { label: "Schedule Demo", href: "/book-a-demo" },
];

"use client";

import Link from "next/link";
import { ChevronDown } from "lucide-react";
import { useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
import type { NavItem } from "@/types/navigation";

function MobileNavGroup({
  item,
  onNavigate,
}: {
  item: NavItem;
  onNavigate: () => void;
}) {
  const [expanded, setExpanded] = useState(false);

  if (!item.children) {
    return (
      <Link
        href={item.href}
        onClick={onNavigate}
        className="block rounded-lg px-3 py-3 text-[15px] font-medium text-[#082753] no-underline transition-colors hover:bg-[#21cfff12]"
      >
        {item.label}
      </Link>
    );
  }

  return (
    <div>
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between rounded-lg px-3 py-3 text-[15px] font-medium text-[#082753] transition-colors hover:bg-[#21cfff12]"
      >
        {item.label}
        <ChevronDown
          className={`h-4 w-4 text-[#082753] transition-transform duration-200 ${expanded ? "rotate-180" : ""}`}
        />
      </button>

      {expanded && (
        <div className="ml-3 border-l border-[#e5e7eb] pl-3">
          {item.children.map((child) => {
            const content = (
              <>
                <span className="text-[14px] font-medium text-[#082753]">
                  {child.label}
                </span>
                {child.comingSoon && (
                  <span
                    className="inline-flex items-center rounded px-1.5 py-0.5 text-[9px] font-bold leading-none text-[#1890ff]"
                    style={{
                      backgroundColor: "#e6f7ff",
                      border: "1px solid #91d5ff",
                    }}
                  >
                    Coming Soon
                  </span>
                )}
              </>
            );

            if (child.comingSoon) {
              return (
                <div
                  key={child.href}
                  className="flex cursor-default items-center gap-2 rounded-lg px-3 py-2.5 opacity-60"
                >
                  {content}
                </div>
              );
            }

            if (child.external) {
              return (
                <a
                  key={child.href}
                  href={child.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={onNavigate}
                  className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-[#21cfff12]"
                >
                  {content}
                </a>
              );
            }

            return (
              <Link
                key={child.href}
                href={child.href}
                onClick={onNavigate}
                className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-[#21cfff12]"
              >
                {content}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

export function MobileNav({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  return (
    <Sheet open={open} onOpenChange={onClose}>
      <SheetContent side="right" className="flex w-[300px] flex-col p-0">
        {/* Header */}
        <SheetHeader className="border-b border-[#e5e7eb] px-4 py-4">
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg font-bold text-[#082753]">
              Boldteq
            </SheetTitle>
          </div>
        </SheetHeader>

        {/* Nav links */}
        <div className="flex flex-col gap-0.5 overflow-y-auto px-2 py-4">
          {NAV_ITEMS.map((item) => (
            <MobileNavGroup
              key={item.label}
              item={item}
              onNavigate={onClose}
            />
          ))}
        </div>

        {/* CTA buttons */}
        <div className="mt-auto space-y-3 border-t border-[#e5e7eb] px-4 py-4">
          {/* Login */}
          <a
            href={CTA_NAV[0].href}
            target="_blank"
            rel="noopener noreferrer"
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[10px] border border-[#082753] bg-transparent px-5 py-2.5 text-[13px] font-bold text-[#082753] no-underline transition-colors hover:bg-[#082753] hover:text-white"
          >
            {CTA_NAV[0].label}
          </a>

          {/* Schedule Demo */}
          <Link
            href={CTA_NAV[1].href}
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[0.75rem] bg-gradient-to-r from-[#21cfff] to-[#019ae6] px-5 py-2.5 text-[13px] font-bold text-white no-underline"
          >
            {CTA_NAV[1].label}
          </Link>
        </div>
      </SheetContent>
    </Sheet>
  );
}

