// ─── Newsletter (client component for form state) ─────────────────────────────

function FooterNewsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!email) return;
    setSubmitting(true);
    try {
      // TODO: wire to your email collection endpoint
      await new Promise<void>((resolve) => setTimeout(resolve, 800));
      setStatus("success");
      setEmail("");
    } catch {
      setStatus("error");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    /* .footer-newsletter-card */
    <div
      className="flex flex-col gap-2.5 rounded-[20px] p-[30px]"
      style={{
        backgroundColor: "rgba(255,255,255,0.3)",
        backgroundImage: "radial-gradient(circle, #092854, rgba(9,41,85,0.67))",
        border: "0.5px solid rgba(5,186,254,0.38)",
        boxShadow: "0 0 50px rgba(0,0,0,0.2), inset 0 0 100px #092955",
      }}
    >
      {/* Title block */}
      <div className="flex flex-col gap-0">
        {/* "Join 500+ Subscribers" pill */}
        <div className="mb-[15px] flex items-center gap-2.5">
          <div
            className="flex items-center gap-1.5 rounded-[20px] px-[13px] py-0.5 text-[13px] leading-[14px]"
            style={{
              backgroundColor: "rgba(33,207,255,0.07)",
              border: "1.5px solid #05bafe",
            }}
          >
            <Image
              src="/images/webflow/Layer_1-57.svg"
              alt="sparkle icon"
              width={14}
              height={14}
              className="h-3.5 w-3.5"
            />
            <p className="m-0 text-left text-[12px] font-bold leading-tight text-white">
              Join 500+ Subscribers
            </p>
          </div>
        </div>

        {/* Heading */}
        <h2 className="m-0 text-left text-[22px] font-bold leading-tight text-white">
          Agency Growth Insights{" "}
          <span style={{ color: "#05bafe" }}>
            <br />
            Delivered Monthly
          </span>
        </h2>

        {/* Body */}
        <p
          className="mt-1 text-[14px] leading-6"
          style={{ color: "#c0dbff" }}
        >
          Smart growth strategies, CRM playbooks, industry trends, early product
          updates, and member-only offers — designed for modern agencies.
        </p>
      </div>

      {/* Form */}
      <div className="mt-[13px]">
        {status === "success" ? (
          <div className="rounded-xl bg-[#def4ff] px-4 py-3 text-sm font-medium text-[#082753]">
            Thank you! Your submission has been received!
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="flex flex-col gap-6">
            <div className="relative flex flex-col gap-1">
              <input
                type="email"
                name="email"
                id="footer-email"
                placeholder="Enter your email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="min-h-[55px] w-full rounded-lg border border-[#edeff3] px-3 py-2 pr-[110px] text-[14px] leading-5 text-[#23272f] outline-none placeholder:text-[#525f75] focus:border-[#b1bbc8]"
                style={{ fontFamily: "inherit" }}
              />
              <button
                type="submit"
                disabled={submitting}
                className="absolute right-[1.5%] top-1/2 -translate-y-1/2 inline-flex items-center justify-center overflow-hidden rounded-[10px] px-5 py-3 text-[16px] font-bold text-white disabled:opacity-70"
                style={{
                  background: "linear-gradient(90deg, #21cfff, #019ae6)",
                  fontFamily: "inherit",
                }}
              >
                {submitting ? "..." : "Get Started"}
              </button>
            </div>
            {status === "error" && (
              <p className="text-sm text-red-400">
                Oops! Something went wrong. Please try again.
              </p>
            )}
          </form>
        )}
      </div>

      {/* Privacy line */}
      <div className="mt-1.5 flex items-center gap-1.5">
        <Image
          src="/images/webflow/Vector-24.svg"
          alt="verified icon"
          width={14}
          height={14}
          className="h-3.5 w-3.5 shrink-0"
        />
        <p
          className="m-0 text-[13px] font-normal"
          style={{ color: "rgba(181,211,245,0.51)" }}
        >
          100% privacy guaranteed. Unsubscribe anytime.
        </p>
      </div>
    </div>
  );
}

