function FooterLinkColumn({
  title,
  links,
}: {
  title: string;
  links: FooterLink[];
}) {
  return (
    <div className="flex flex-col gap-4">
      {/* Column title */}
      <p className="m-0 text-[18px] font-bold capitalize leading-[22px] text-white">
        {title}
      </p>
      {/* Links */}
      <div className="flex flex-col gap-4">
        {links.map((link) => {
          const baseClass =
            "text-[16px] leading-6 no-underline transition-colors duration-300";
          const colorClass = "text-white/80 hover:text-white";
          const disabledStyle = link.comingSoon
            ? "pointer-events-none opacity-60"
            : "";

          const inner = (
            <span className="flex items-center gap-2">
              {link.label}
              {link.comingSoon && (
                <span className="rounded bg-white/10 px-1.5 py-0.5 text-[10px] leading-none text-white/80">
                  Soon
                </span>
              )}
            </span>
          );

          if (link.external) {
            return (
              <a
                key={link.href + link.label}
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
                className={`${baseClass} ${colorClass} ${disabledStyle}`}
              >
                {inner}
              </a>
            );
          }

          return (
            <Link
              key={link.href + link.label}
              href={link.href}
              className={`${baseClass} ${colorClass} ${disabledStyle}`}
            >
              {inner}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

